\section*{Analytic Toeplitz Algebras of Single-Vertex Rank-2 Graphs}

Let $\Lambda$ be a single-vertex rank-2 graph (2-graph) with $m$ edges of degree $(1,0)$, denoted by $E = \{e_1, \dots, e_m\}$, and $n$ edges of degree $(0,1)$, denoted by $F = \{f_1, \dots, f_n\}$.

\subsection*{1. Generators and Representation}
The path category $\Lambda$ is completely determined by the factorization property: for every pair $(e_i, f_j) \in E \times F$, there exists a unique pair $(f_l, e_k) \in F \times E$ such that $e_i f_j = f_l e_k$.

Let $\ell^2(\Lambda)$ be the Fock space with orthonormal basis $\{e_\alpha : \alpha \in \Lambda\}$. The **analytic Toeplitz algebra** $\mathcal{T}^+(\Lambda)$ is the weakly closed non-self-adjoint operator algebra generated by the left regular representation of $\Lambda$ on $\ell^2(\Lambda)$:
\[
\mathcal{T}^+(\Lambda) = \operatorname{Alg}(S_1, \dots, S_m, T_1, \dots, T_n) \subset \mathcal{B}(\ell^2(\Lambda))
\]
where $S_i = L_{e_i}$ and $T_j = L_{f_j}$ are isometry generators defined by $L_\alpha e_\beta = e_{\alpha\beta}$.

\subsection*{2. Commutation Relation Matrix $u$}
The factorization rule is encoded by a unique bijection $\theta: \{1,\dots,m\} \times \{1,\dots,n\} \to \{1,\dots,n\} \times \{1,\dots,m\}$. 

We express this bijection via an $mn \times mn$ permutation matrix $u = (u_{(i,j),(l,k)})$, where $i,k \in \{1,\dots,m\}$ and $j,l \in \{1,\dots,n\}$, defined by:
\[
u_{(i,j),(l,k)} = 
\begin{cases} 
1 & \text{if } e_i f_j = f_l e_k, \\ 
0 & \text{otherwise.} 
\end{cases}
\]
The generators satisfy the non-commutative algebraic relation governed by $u$:
\[
S_i T_j = \sum_{k=1}^m \sum_{l=1}^n u_{(i,j),(l,k)} T_l S_k \quad \forall \, i \in \{1,\dots,m\}, \, j \in \{1,\dots,n\}.
\]

\subsection*{3. Classification up to Isometric Isomorphism}
Two single-vertex 2-graphs $\Lambda_1$ and $\Lambda_2$ with edge sets $(E_1, F_1)$ and $(E_2, F_2)$ are isomorphic ($\Lambda_1 \cong \Lambda_2$) if and only if their commutation matrices $u_1$ and $u_2$ are equivalent up to generator relabeling.

\begin{theorem}[Classification]
Let $\Lambda_1$ and $\Lambda_2$ be single-vertex rank-2 graphs with commutation matrices $u_1$ and $u_2$. The following statements are equivalent:
\begin{enumerate}
    \item $\mathcal{T}^+(\Lambda_1)$ and $\mathcal{T}^+(\Lambda_2)$ are completely isometrically isomorphic as operator algebras.
    \item $\mathcal{T}^+(\Lambda_1)$ and $\mathcal{T}^+(\Lambda_2)$ are isometrically isomorphic as Banach algebras.
    \item The 2-graphs $\Lambda_1$ and $\Lambda_2$ are isomorphic ($\Lambda_1 \cong \Lambda_2$).
    \item There exist permutation matrices $P \in M_m$ and $Q \in M_n$ such that 
    \[
    u_2 = (P \otimes Q) \, u_1 \, (Q^T \otimes P^T).
    \]
\end{enumerate}
\end{theorem}

